        test('generates transform map with server module script', async () => {
            const project = ctx.createProject({
                rootDir: __dirname,
                config: {
                    fluentDir: 'modules/fluent',
                    serverModulesDir: 'modules/server',
                },
            })
            const file = project.addFile(`${__dirname}/modules/fluent/import-set.now.ts`)
            project.addFile(`${__dirname}/modules/server/transform-map-script.js`)
            project.registerExplicitId('sys_transform_map', 'test_transform_map_id', 'test_transform_map_id')
            project.registerExplicitId('sys_transform_entry', 'test_transform_entry_id', 'test_transform_entry_id')
            const output = await file.getOutput()
            expect(await project.getDiagnostics()).toHaveLength(0)
            expect(output).toHaveLength(2) // 1 map + 1 entry

            const mapOutput = output.find((o) => o.content.includes('sys_transform_map'))
            expect(mapOutput).toBeDefined()
            if (!mapOutput) {
                throw new Error('Transform map output not found')
            }

            const expected = await readFile(`${__dirname}/xml/sys-transform-map-with-module.xml`, 'utf8')
            expect(mapOutput.content.trim()).toEqual(expected.trim())
        })

